import{_ as t,o as r,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Perioden, Aktualisierung und Zeit","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/05.hintergrund/03.perioden-und-zeit.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","filePath":"de/adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","lastUpdated":null}'),i={name:"de/adapter/sourceanalytix/hintergrund/perioden-und-zeit.md"};function d(h,e,s,o,u,l){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="perioden-aktualisierung-und-zeit" tabindex="-1">Perioden, Aktualisierung und Zeit <a class="header-anchor" href="#perioden-aktualisierung-und-zeit" aria-label="Permalink to &quot;Perioden, Aktualisierung und Zeit&quot;">​</a></h1><p><a id="values-updated-live-midnight"></a></p><h2 id="wann-werden-werte-aktualisiert-–-live-oder-um-mitternacht" tabindex="-1">Wann werden Werte aktualisiert – live oder um Mitternacht? <a class="header-anchor" href="#wann-werden-werte-aktualisiert-–-live-oder-um-mitternacht" aria-label="Permalink to &quot;Wann werden Werte aktualisiert – live oder um Mitternacht?&quot;">​</a></h2><p>Beides. Die laufenden Werte rechnet SourceAnalytix mit jedem neuen Wert der Quelle sofort neu. Um Mitternacht schreibt es zusätzlich die Vorperioden wie „gestern“ und beginnt die neuen Perioden bei 0.</p><table tabindex="0"><thead><tr><th>Werte</th><th>Wann</th></tr></thead><tbody><tr><td>Gesamtstand und laufende Perioden (Tag bis Jahr, Wochentage, Wochen, Monate, Quartale)</td><td>bei jedem neuen Wert der Quelle, wenn er sich ändert</td></tr><tr><td>Vorperioden (gestern, letzte Woche …)</td><td>beim Wechsel der Periode, mit Zeitstempel 23:59:59 Uhr am letzten Tag</td></tr><tr><td>Startwerte in den Einstellungen der Quelle</td><td>beim Wechsel der Periode</td></tr></tbody></table><p>Sendet die Quelle eine Zeit lang nichts, bleiben auch die Werte von SourceAnalytix stehen.</p><p>Um 0:00 Uhr endet immer der Tag, montags die Woche, am 1. der Monat, am 1. Januar, April, Juli und Oktober das Quartal und am 1. Januar das Jahr. Werte, die während des Wechsels eintreffen, werden zwischengespeichert und danach der Reihe nach verrechnet.</p><p>War ioBroker um Mitternacht aus, holt SourceAnalytix den Wechsel beim Start nach, siehe <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker war um Mitternacht aus</a>.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Wo finde ich gestern, letzte Woche, letzten Monat?</a> · <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Absturz oder Wechsel zur falschen Zeit</a></p><p><a id="week-52-53-have-values"></a></p><h2 id="warum-zeigt-woche-52-53-werte-im-neuen-jahr" tabindex="-1">Warum zeigt Woche 52/53 Werte im neuen Jahr? <a class="header-anchor" href="#warum-zeigt-woche-52-53-werte-im-neuen-jahr" aria-label="Permalink to &quot;Warum zeigt Woche 52/53 Werte im neuen Jahr?&quot;">​</a></h2><p>Weil SourceAnalytix Kalenderwochen nach ISO 8601 zählt: Die Woche beginnt am Montag, und Woche 1 ist die Woche mit dem ersten Donnerstag des Jahres. Anfang Januar kann es deshalb noch Woche 52 oder 53 des Vorjahres sein.</p><table tabindex="0"><thead><tr><th>Tage</th><th>Kalenderwoche</th></tr></thead><tbody><tr><td>29.12.2025 bis 4.1.2026</td><td>Woche 1 von 2026</td></tr><tr><td>28.12.2026 bis 3.1.2027</td><td>Woche 53 von 2026</td></tr></tbody></table><ul><li>„Aktuelle Woche“ zählt immer die ganze Woche, auch über den Jahreswechsel. „Aktuelles Jahr“ beginnt am 1. Januar bei 0.</li><li>Die Wochen unter <code>currentYear</code> zeigen nur Wochen des laufenden Jahres.</li><li>Im Jahresarchiv steht jede Woche im Ordner ihres ISO-Jahres, Woche 53 von 2026 also unter <code>2026</code>, auch mit den Januartagen.</li></ul><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#happens-turn-year">Was passiert zum Jahreswechsel?</a></p><p><a id="sourceanalytix-calculate-retroactively-only-activation"></a></p><h2 id="berechnet-sourceanalytix-ruckwirkend-oder-erst-ab-aktivierung" tabindex="-1">Berechnet SourceAnalytix rückwirkend oder erst ab Aktivierung? <a class="header-anchor" href="#berechnet-sourceanalytix-ruckwirkend-oder-erst-ab-aktivierung" aria-label="Permalink to &quot;Berechnet SourceAnalytix rückwirkend oder erst ab Aktivierung?&quot;">​</a></h2><p>Ab Aktivierung. Kennst du die Zählerstände zu Beginn der laufenden Perioden, trägst du sie als Startwerte ein, dann zählt der Verbrauch seit Periodenbeginn mit.</p><p>Der Assistent „Quelle hinzufügen“ fragt das im Schritt „Startwerte“ ab:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Was passiert</th></tr></thead><tbody><tr><td>„Ab jetzt zählen“</td><td>Alle Perioden beginnen jetzt bei 0.</td></tr><tr><td>„Verbrauch seit Periodenbeginn mitzählen“</td><td>Du trägst die Zählerstände zu Beginn von Tag, Woche, Monat, Quartal und Jahr ein. Leere Felder zählen ab jetzt.</td></tr></tbody></table><p>Frühere Perioden wie das Vorjahr kann SourceAnalytix nicht erzeugen, und die Vorperioden füllen sich erst nach dem ersten Wechsel. Leistungsquellen (W) zählen immer ab Aktivierung, weil sie keinen Zählerstand liefern.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a></p><p><a id="week-month-quarter-year-values"></a></p><h2 id="warum-unterscheiden-sich-wochen-monats-quartals-und-jahreswerte" tabindex="-1">Warum unterscheiden sich Wochen-, Monats-, Quartals- und Jahreswerte? <a class="header-anchor" href="#warum-unterscheiden-sich-wochen-monats-quartals-und-jahreswerte" aria-label="Permalink to &quot;Warum unterscheiden sich Wochen-, Monats-, Quartals- und Jahreswerte?&quot;">​</a></h2><p>Weil jede Periode zu einem anderen Zeitpunkt beginnt und ihren eigenen Startwert hat. Der Verbrauch ist immer Gesamtstand minus Startwert dieser Periode.</p><p>Typische Gründe:</p><ul><li><strong>Woche über die Monatsgrenze:</strong> Am Samstag, 3.10.2026, zählt der Monat drei Tage, die Woche fünf, denn sie begann am Montag, 28.9.</li><li><strong>Aktivierung mitten in der Periode:</strong> Ohne Startwerte enthalten Monat, Quartal und Jahr zuerst gleich viel.</li><li><strong>Rundung:</strong> Jeder Periodenwert wird für sich gerundet. Die Summe der Tage kann in der letzten Stelle abweichen.</li><li><strong>Grundpreis:</strong> Er wird monatlich gebucht, nicht auf die Tage verteilt, siehe <a href="./../anleitungen/preise-und-kosten#include-monthly-base-fee">Grundpreis</a>.</li></ul><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">Welche States gibt es für Wochen, Monate und Wochentage?</a></p>',28)])])}const m=t(i,[["render",d]]);export{g as __pageData,m as default};
